operation.expression:
(: -------------------------------------------- :)
(: Normalize scalar fields from request :)
(: -------------------------------------------- :)
let $firstName    := normalize-space(string($input.request.personFirstName))
let $middleName   := normalize-space(string($input.request.personMiddleName))
let $lastName     := normalize-space(string($input.request.personLastName))
let $dob          := normalize-space(string($input.request.personDob))
let $taxIdLast4   := normalize-space(string($input.request.partyTaxIdLast4))
let $roleType     := normalize-space(string( $input.request/roles/roleType/code ))
let $statusCode   := normalize-space(string( $input.request/roles/status/code ))

(: -------------------------------------------- :)
(: Build contact mechanism filters (ARRAY) :)
(: -------------------------------------------- :)
let $contactFilters :=
  for $cm in $input.request.contactMechanisms
  let $value := normalize-space(string($cm/contactMechanismValue))
  let $code  := normalize-space(string($cm/contactMechanismType/code))
  return
    (
      if ($value != "")
      then concat(
        '{"fieldName":"party_investor.contact_mechanisms.contactMechanismValue",',
        '"comparator":"EQUALS","fieldValue":"', $value, '"}'
      ) else (),

      if ($code != "")
      then concat(
        '{"fieldName":"party_investor.contact_mechanisms.contactMechanismType.Code",',
        '"comparator":"EQUALS","fieldValue":"', $code, '"}'
      ) else ()
    )

(: -------------------------------------------- :)
(: Build address filters (ARRAY aware) :)
(: -------------------------------------------- :)
let $addressFilters :=
  for $addr in $input.request.addresses
  let $city       := normalize-space(string($addr/city))
  let $postalCode := normalize-space(string($addr/postalCode))
  return
    (
      if ($city != "")
      then concat(
        '{"fieldName":"party_investor.addresses.city","comparator":"EQUALS","fieldValue":"',
        $city, '"}'
      ) else (),

      if ($postalCode != "")
      then concat(
        '{"fieldName":"party_investor.addresses.postalCode","comparator":"EQUALS","fieldValue":"',
        $postalCode, '"}'
      ) else ()
    )

(: -------------------------------------------- :)
(: Build base + conditional filters :)
(: -------------------------------------------- :)
let $filters :=
(
  (: Role Type :)
  if ($roleType != "")
  then concat(
    '{"fieldName":"party_investor.roles.roleTypeId.Code","comparator":"EQUALS","fieldValue":"',
    $roleType, '"}'
  ) else (),

  (: Status :)
  if ($statusCode != "")
  then concat(
    '{"fieldName":"party_investor.roles.statusId.Code","comparator":"EQUALS","fieldValue":"',
    $statusCode, '"}'
  ) else (),

  (: Person fields :)
  if ($firstName != "")
  then concat(
    '{"fieldName":"party_investor.personFirstName","comparator":"EQUALS","fieldValue":"',
    $firstName, '"}'
  ) else (),

  if ($middleName != "")
  then concat(
    '{"fieldName":"party_investor.personMiddleName","comparator":"EQUALS","fieldValue":"',
    $middleName, '"}'
  ) else (),

  if ($lastName != "")
  then concat(
    '{"fieldName":"party_investor.personLastName","comparator":"EQUALS","fieldValue":"',
    $lastName, '"}'
  ) else (),

  if ($dob != "")
  then concat(
    '{"fieldName":"party_investor.personBirthDate","comparator":"EQUALS","fieldValue":"',
    $dob, '"}'
  ) else (),

  if ($taxIdLast4 != "")
  then concat(
    '{"fieldName":"party_investor.partyTaxIdLast4","comparator":"EQUALS","fieldValue":"',
    $taxIdLast4, '"}'
  ) else (),

concat(
  '{"fieldName":"party_investor.partyType.Code","comparator":"EQUALS","fieldValue":"2102"}',''
),


  $contactFilters,
  $addressFilters
)

(: -------------------------------------------- :)
(: Join filters and build final JSON :)
(: -------------------------------------------- :)
let $filtersJson := string-join($filters, ",")

return concat(
  '{"entityType":"party_investor","search":"*",',
  '"pageSize":25,"filters":{"filter":[',
  $filtersJson,
  ']}}'
)

let $req := $input.request

let $roleCode   := data($req/roles/roleType/code)
let $roleName   :=
  if ($roleCode = '4160') then 'Individual Investor'
  else ''

let $statusCode := data($req/roles/status/code)
let $statusName :=
  if ($statusCode = '1801') then 'Active'
  else if ($statusCode = '1802') then 'Inactive'
  else if ($statusCode = '1803') then 'Pending Active'
  else if ($statusCode = '1804') then 'Pending inactive'
  else ''

return
<criteria>

  <!-- ========= MATERIALIZATIONS ========= -->
  {
    if (
      exists( $input.request[1]/personFirstName )
      or exists($req/personLastName)
      or exists($req/personDob)
      or exists($req/partyTaxIdLast4)
    )
    then <materializations>CorePartyInfo</materializations>
    else ()
  }

  {
    if (exists($req/roles))
    then <materializations>Roles</materializations>
    else ()
  }

  {
    if (exists($req/contactMechanisms))
    then <materializations>ContactMechanisms</materializations>
    else ()
  }

  <!-- ========= PARTY TYPE ========= -->
  <partyType>
    <code>2102</code>
    <name>Person</name>
    <effectiveReferenceId>2102</effectiveReferenceId>
  </partyType>

  <!-- ========= PERSON FIELDS ========= -->
  { if (exists($req/personFirstName))
    then <personFirstName>{ data($req/personFirstName) }</personFirstName>
    else () }

  { if (exists($req/personLastName))
    then <personLastName>{ data($req/personLastName) }</personLastName>
    else () }

  { if (exists($req/personDob))
    then <personDob>{ data($req/personDob) }</personDob>
    else () }

  { if (exists($req/partyTaxIdLast4))
    then <partyTaxIdLast4>{ data($req/partyTaxIdLast4) }</partyTaxIdLast4>
    else () }

  <!-- ========= ROLES ========= -->
{
  if ($roleCode != '' or $statusCode != '')
  then
    <roles>
      <role>
        {
          if ($roleCode != '')
          then
            <roleType>
              <code>{ $roleCode }</code>
              <name>{ $roleName }</name>
              <effectiveReferenceId>{ $roleCode }</effectiveReferenceId>
            </roleType>
          else ()
        }
        {
          if ($statusCode != '')
          then
            <status>
              <code>{ $statusCode }</code>
              <name>{ $statusName }</name>
              <effectiveReferenceId>{ $statusCode }</effectiveReferenceId>
            </status>
          else ()
        }
      </role>
    </roles>
  else ()
}

  <!-- ===== CONTACT MECHANISMS ===== -->
  {
    for $cm in $req/contactMechanisms
    let $cmCode := data($cm/contactMechanismType/code)
    let $cmName :=
      if ($cmCode = '301') then 'Email Address'
      else if ($cmCode = '303') then 'Phone Number'
      else if ($cmCode = '306') then 'Mobile Phone Number'
      else if ($cmCode = '311') then 'Landline'
      else ''

    return
      <contactMechanisms>
        <contactMechanismValue>{ data($cm/contactMechanismValue) }</contactMechanismValue>
        <contactMechanismType>
          <code>{ $cmCode }</code>
          <name>{ $cmName }</name>
          <effectiveReferenceId>{ $cmCode }</effectiveReferenceId>
        </contactMechanismType>
      </contactMechanisms>
  }

</criteria>

let $criteria := $temp.requestDetail  (: your already-built criteria :)
let $resp := $output.EntireResponse 

return
<criteria>

  <!-- ===================== -->
  <!-- EXISTING CRITERIA CONTENT -->
  <!-- ===================== -->
  {
    $criteria/*
  }
  <!-- ===================== -->
  <!-- PERSONS (FROM ENTIRERESPONSE) -->
  <!-- ===================== -->
  {
    for $rec in $resp/searchResult/records
    return
      <persons>

        <personLastName>
          { data($rec/party_investor.personLastName) }
        </personLastName>

        <personFirstName>
          { data($rec/party_investor.personFirstName) }
        </personFirstName>

        <tinTypeId>
          { data($rec/party_investor.taxIdentificationType/Code) }
        </tinTypeId>

        {
          if (exists($rec/party_investor.personMiddleInitial)) then
            <personMiddleInitial>
              { data($rec/party_investor.personMiddleInitial) }
            </personMiddleInitial>
          else ()
        }

        {
          if (exists($rec/party_investor.personBirthDate)) then
            <personBirthDate>
              { data($rec/party_investor.personBirthDate) }
            </personBirthDate>
          else ()
        }

        {
          if (exists($rec/party_investor.personMiddleName)) then
            <personMiddleName>
              { data($rec/party_investor.personMiddleName) }
            </personMiddleName>
          else ()
        }

        <partyTaxIdLast4>
          { data($rec/party_investor.partyTaxIdLast4) }
        </partyTaxIdLast4>

        <effectiveReferenceId>
          { data($rec/_meta/id) }
        </effectiveReferenceId>

        <partyId>
          { data($rec/_meta/id) }
        </partyId>

      </persons>
  }

</criteria>

