let $resp := $output.EntireResponse 

return
<criteria>

  <!-- ===================== -->
  <!-- EXISTING CRITERIA CONTENT -->
  <!-- ===================== -->
  {
    $criteria/*
  }
  <!-- ===================== -->
  <!-- PERSONS (FROM ENTIRERESPONSE) -->
  <!-- ===================== -->
  {
    for $rec in $resp/searchResult/records
    return
      <persons>

        <personLastName>
          { data($rec/party_investor.personLastName) }
        </personLastName>

        <personFirstName>
          { data($rec/party_investor.personFirstName) }
        </personFirstName>

        <tinTypeId>
          { data($rec/party_investor.taxIdentificationType/Code) }
        </tinTypeId>

        {
          if (exists($rec/party_investor.personMiddleInitial)) then
            <personMiddleInitial>
              { data($rec/party_investor.personMiddleInitial) }
            </personMiddleInitial>
          else ()
        }

        {
          if (exists($rec/party_investor.personBirthDate)) then
            <personBirthDate>
              { data($rec/party_investor.personBirthDate) }
