let $req := $input.request
let $roleCode := data($req/roles/roleType/code)
let $roleName :=
  if ($roleCode = '4160') then 'Individual Investor'
  else ''

let $statusCode := data($req/roles/status/code)
let $statusName :=
  if ($statusCode = '1801') then 'Active'
  else if ($statusCode = '1802') then 'Inactive'
  else if ($statusCode = '1803') then 'Pending Active'
  else if ($statusCode = '1804') then 'Pending inactive'
  else ''

let $cm := $req/contactMechanisms[1]
let $cmCode := data($cm/contactMechanismType/code)

let $cmName :=
  if ($cmCode = '301') then 'Email Address'
  else if ($cmCode = '303') then 'Phone Number'
  else if ($cmCode = '306') then 'Mobile Phone Number'
  else if ($cmCode = '311') then 'Landline'
  else ''

return
<temp_criteria>

    { if (exists($req/personFirstName))
      then <personFirstName>{ data($req/personFirstName) }</personFirstName>
      else () }

    { if (exists($req/personMiddleName))
      then <personMiddleName>{ data($req/personMiddleName) }</personMiddleName>
      else () }

    { if (exists($req/personLastName))
      then <personLastName>{ data($req/personLastName) }</personLastName>
      else () }

    { if (exists($req/personDob))
      then <personDob>{ data($req/personDob) }</personDob>
      else () }

    { if (exists($req/partyTaxIdLast4))
      then <partyTaxIdLast4>{ data($req/partyTaxIdLast4) }</partyTaxIdLast4>
      else () }

    <!-- ✅ ROLES -->
    {
      if ($roleCode != '' or $statusCode != '')
      then
        <roles>
          {
            if ($roleCode != '')
            then
              <roleType>
                <name>{ $roleName }</name>
                <code>{ $roleCode }</code>
              </roleType>
            else ()
          }
          {
            if ($statusCode != '')
            then
              <status>
                <name>{ $statusName }</name>
                <code>{ $statusCode }</code>
              </status>
            else ()
          }
        </roles>
      else ()
    }

    <!-- ✅ PARTY TYPE -->
  <partyType>
    <code>2102</code>
    <name>Person</name>
    <effectiveReferenceId>2102</effectiveReferenceId>
  </partyType>

    <!-- ✅ CONTACT MECHANISMS -->
    {
      if (exists($cm))
      then
        <contactMechanisms>
          <contactMechanismValue>
            { data($cm/contactMechanismValue) }
          </contactMechanismValue>

          <contactMechanismType>
            <name>{ $cmName }</name>
            <code>{ $cmCode }</code>
            <effectiveReferenceId>{ $cmCode }</effectiveReferenceId>
          </contactMechanismType>
        </contactMechanisms>
      else ()
    }

</temp_criteria>

let $req := $input.request
let $resp := $output.EntireResponse 

(: ✅ Correct hits path :)
let $hits := number($resp/*:searchResult/*:hits)

(: --- ROLE LOGIC --- :)
let $roleCode := data($req/roles/roleType/code)
let $roleName :=
  if ($roleCode = '4160') then 'Individual Investor'
  else ''

let $statusCode := data($req/roles/status/code)
let $statusName :=
  if ($statusCode = '1801') then 'Active'
  else if ($statusCode = '1802') then 'Inactive'
  else if ($statusCode = '1803') then 'Pending Active'
  else if ($statusCode = '1804') then 'Pending inactive'
  else ''

(: --- CONTACT LOGIC --- :)
let $cm := $req/contactMechanisms[1]
let $cmCode := data($cm/contactMechanismType/code)
let $cmName :=
  if ($cmCode = '301') then 'Email Address'
  else if ($cmCode = '303') then 'Phone Number'
  else if ($cmCode = '306') then 'Mobile Phone Number'
  else if ($cmCode = '311') then 'Landline'
  else ''

(: --- ADDRESS LOGIC --- :)
let $addr := $req/addresses[1]

return
<exactSearchResponseCopy>  

  <!-- ✅ BASIC INFO -->
  { if (normalize-space($req/personFirstName) != '') then <personFirstName>{data($req/personFirstName)}</personFirstName> else () }
  { if (normalize-space($req/personMiddleName) != '') then <personMiddleName>{data($req/personMiddleName)}</personMiddleName> else () }
  { if (normalize-space($req/personLastName) != '') then <personLastName>{data($req/personLastName)}</personLastName> else () }
  { if (normalize-space($req/personDob) != '') then <personDob>{data($req/personDob)}</personDob> else () }
  { if (normalize-space($req/partyTaxIdLast4) != '') then <partyTaxIdLast4>{data($req/partyTaxIdLast4)}</partyTaxIdLast4> else () }

  <!-- ✅ ROLES -->
  {
    if ($roleCode != '' or $statusCode != '')
    then
      <roles>
        {
          if ($roleCode != '')
          then
            <roleType>
              <name>{ $roleName }</name>
              <code>{ $roleCode }</code>
              <effectiveReferenceId>{ $roleCode }</effectiveReferenceId>
            </roleType>
          else ()
        }
        {
          if ($statusCode != '')
          then
            <status>
              <name>{ $statusName }</name>
              <code>{ $statusCode }</code>
              <effectiveReferenceId>{ $statusCode }</effectiveReferenceId>
            </status>
          else ()
        }
      </roles>
    else ()
  }

  <!-- ✅ PARTY TYPE -->
  <partyType>
    <code>2102</code>
    <name>Person</name>
    <effectiveReferenceId>2102</effectiveReferenceId>
  </partyType>

  <!-- ✅ ADDRESSES -->
  {
    if ($addr)
    then
      <addresses>

        { if (normalize-space($addr/streetLine1) != '')
          then <streetLine1>{data($addr/streetLine1)}</streetLine1>
          else () }

        { if (normalize-space($addr/streetLine2) != '')
          then <streetLine2>{data($addr/streetLine2)}</streetLine2>
          else () }

        { if (normalize-space($addr/city) != '')
          then <city>{data($addr/city)}</city>
          else () }

        { if (normalize-space($addr/state) != '')
          then <state>{data($addr/state)}</state>
          else () }

        { if (normalize-space($addr/postalCode) != '')
          then <postalCode>{data($addr/postalCode)}</postalCode>
          else () }

        {
          if ($addr/country)
          then
            <country>
              { if (normalize-space($addr/country/name) != '')
                then <name>{data($addr/country/name)}</name>
                else () }

              { if (normalize-space($addr/country/code) != '')
                then <code>{data($addr/country/code)}</code>
                else () }
            </country>
          else ()
        }

      </addresses>
    else ()
  }

  <!-- ✅ CONTACT -->
  {
    if ($cmCode != '')
    then
      <contactMechanisms>
        { if (normalize-space($cm/contactMechanismValue) != '') then <contactMechanismValue>{data($cm/contactMechanismValue)}</contactMechanismValue> else () }
        <contactMechanismType>
          <name>{ $cmName }</name>
          <code>{ $cmCode }</code>
          <effectiveReferenceId>{ $cmCode }</effectiveReferenceId>
        </contactMechanismType>
      </contactMechanisms>
    else ()
  }

  <!-- ✅ MATERIALIZATIONS -->
  {
    if ($req/personFirstName or $req/personLastName or $req/personDob or $req/partyTaxIdLast4)
    then <materializations>CorePartyInfo</materializations>
    else ()
  }

  { if ($req/roles) then <materializations>Roles</materializations> else () }
  { if ($req/contactMechanisms) then <materializations>ContactMechanisms</materializations> else () }
  { if ($req/addresses) then <materializations>Addresses</materializations> else () }

  <!-- ✅ PERSONS -->
  {
    if ($hits > 0)
    then
      for $rec in $resp/*:searchResult/*:records
      return
        <persons>

          { if (normalize-space($rec/*:party_investor.personLastName) != '') then <personLastName>{data($rec/*:party_investor.personLastName)}</personLastName> else () }

          { if (normalize-space($rec/*:party_investor.personFirstName) != '') then <personFirstName>{data($rec/*:party_investor.personFirstName)}</personFirstName> else () }

          { if (normalize-space($rec/*:party_investor.taxIdentificationType/*:Code) != '') then <tinTypeId>{data($rec/*:party_investor.taxIdentificationType/*:Code)}</tinTypeId> else () }

          { if (normalize-space($rec/*:party_investor.personMiddleInitial) != '') then <personMiddleInitial>{data($rec/*:party_investor.personMiddleInitial)}</personMiddleInitial> else () }

          { if (normalize-space($rec/*:party_investor.personMiddleName) != '') then <personMiddleName>{data($rec/*:party_investor.personMiddleName)}</personMiddleName> else () }

          { if (normalize-space($rec/*:party_investor.partyTaxIdLast4) != '') then <partyTaxIdLast4>{data($rec/*:party_investor.partyTaxIdLast4)}</partyTaxIdLast4> else () }

          { if (normalize-space($rec/*:_meta/*:id) != '') then <effectiveReferenceId>{data($rec/*:_meta/*:id)}</effectiveReferenceId> else () }

          { if (normalize-space($rec/*:_meta/*:id) != '') then <partyId>{data($rec/*:_meta/*:id)}</partyId> else () }

        </persons>
    else ()
  }

  <!-- ✅ WARNING -->
  {
    if ($hits = 0)
    then
      <warning>
        <message>No Data Found for specified criteria</message>
        <code>9001</code>
      </warning>
    else ()
  }

</exactSearchResponseCopy>
